// Runs a preloaded program to completion. The responders serve the core on
// their own, so this sequence only owns the run window: wait for the HALT
// instruction to retire, then let the last bus activity drain.
//
// Reset is generated by tb_core_top. A dedicated reset agent belongs in
// phase 3, together with mid-test reset scenarios.
class program_seq extends uvm_sequence #(native_mem_item);

    core_cfg     cfg;
    int unsigned drain_cycles = 16;

    `uvm_object_utils(program_seq)

    function new(string name = "program_seq");
        super.new(name);
    endfunction

    task body();
        if (cfg == null)
            `uvm_fatal("NOCFG", "program_seq needs a core_cfg handle")

        // Do not start counting the timeout while the core is still in reset.
        wait (cfg.rvfi_vif.reset_n === 1'b1);

        fork
            begin : wait_halt
                if (!cfg.stats.halt_e.is_on())
                    cfg.stats.halt_e.wait_trigger();
            end
            begin : watchdog
                repeat (cfg.timeout_cycles) @(posedge cfg.rvfi_vif.clk);
                `uvm_error("TIMEOUT",
                    $sformatf("no HALT after %0d cycles (%0d retirements so far)",
                              cfg.timeout_cycles, cfg.stats.n_retire))
            end
        join_any
        disable fork;

        repeat (drain_cycles) @(posedge cfg.rvfi_vif.clk);
    endtask

endclass
